use core.files as files
use core.process as process
use core.text as text

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    input :: files.read(path) ?? panic("read failed")
    keys := [String]{}
    values := [String]{}
    active := [Bool]{}

    loop row in input.lines() {
        fields :: text.splitn(row, "|", 3)
        if fields.len() != 3 {
            panic("malformed journal record")
        }
        kind :: fields.get(0) ?? panic("malformed journal record")
        key :: fields.get(1) ?? panic("malformed journal record")
        value :: fields.get(2) ?? panic("malformed journal record")
        if key.is_empty() {
            panic("malformed journal record")
        }
        found := false
        loop i in 0..<keys.len() {
            if active[i] && keys[i] == key {
                found = true
                if kind == "put" {
                    values[i] = ~value
                } else if kind == "delete" {
                    if !value.is_empty() {
                        panic("malformed delete record")
                    }
                    active[i] = false
                }
            }
        }
        if kind == "put" {
            if !found {
                keys.push(key)
                values.push(value)
                active.push(true)
            }
        } else if kind == "delete" {
            if !found {
                if !value.is_empty() {
                    panic("malformed delete record")
                }
            }
        } else {
            panic("unknown record kind {kind}")
        }
    }

    loop i in 0..<keys.len() {
        if active[i] {
            print("{keys[i]}={values[i]}")
        }
    }
}
